<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Driven;

use DateTimeImmutable;
use Override;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurpose;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeFilter;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeReadGateway;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\UserConsentPurposes;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\UserConsentPurposesAttributes;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway\UserConsentPurposesFilter;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway\UserConsentPurposesReadGateway;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway\UserConsentPurposesWriteGateway;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\Gateway\GdprConsentGateway;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentListItem;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentMap;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentPurposeItem;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentRecord;
use Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Service\UserConsentPurposeGrant;
use Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Service\UserConsentPurposePending;

final class GdprConsentAdapter implements GdprConsentGateway
{
    use LoggerAwareTrait;

    public function __construct(
        private readonly TenantReadGateway $tenants,
        private readonly UserReadGateway $users,
        private readonly ConsentPurposeReadGateway $purposes,
        private readonly UserConsentPurposesReadGateway $reader,
        private readonly UserConsentPurposesWriteGateway $writer,
        private readonly UserConsentPurposeGrant $grantService,
        private readonly UserConsentPurposePending $pendingService,
    ) {
    }

    /** @return GdprConsentPurposeItem[] */
    #[Override]
    public function pendingPurposes(string $tenant, string $username): array
    {
        $user = $this->resolveUser($tenant, $username);
        if (null === $user) {
            return [];
        }

        $tenantEntity = $this->resolveTenant($tenant);
        if (null === $tenantEntity) {
            return [];
        }

        [, $purposesByKey] = $this->resolveActivePurposes($tenantEntity);
        $pending = $this->pendingService->pending($user, array_values($purposesByKey));

        return array_map(static fn (ConsentPurpose $p): GdprConsentPurposeItem => new GdprConsentPurposeItem(
            uid: $p->uid(),
            key: $p->getKey()->value,
            title: $p->getTitle(),
            description: $p->getDescription(),
            required: $p->isRequired(),
        ), $pending);
    }

    /** @param array<string,bool> $decisions */
    #[Override]
    public function storePurposeDecisions(
        string $tenant,
        string $username,
        array $decisions,
        string $ipAddress,
        string $userAgent
    ): void {
        $user = $this->resolveUser($tenant, $username);
        if (null === $user) {
            $this->logWarning('GdprConsentAdapter: could not resolve user — decisions not stored', [
                'tenant' => $tenant,
                'username' => $username,
            ]);
            return;
        }

        $this->grantService->grant($user, $decisions, $ipAddress, $userAgent);
    }

    /** @return GdprConsentListItem[] */
    #[Override]
    public function listConsents(string $userUid, string $tenantUid): array
    {
        $tenant = new TenantRef($tenantUid);
        $user = new UserRef($userUid);

        [$map, $purposesByKey] = $this->resolveActivePurposes($tenant);
        if ($map->isEmpty()) {
            return [];
        }

        $purposeUids = array_map(static fn (ConsentPurpose $p): string => $p->uid(), $purposesByKey);
        $decisions = [];
        foreach ($this->reader->list((new UserConsentPurposesFilter())->withUser($user)->withConsentPurposes(array_values($purposeUids)))->values() as $consent) {
            $decisions[$consent->getConsentPurpose()->uid()] = $consent;
        }

        $result = [];
        foreach ($purposesByKey as $purpose) {
            $consent = $decisions[$purpose->uid()] ?? null;
            $result[] = new GdprConsentListItem(
                purposeUid: $purpose->uid(),
                purposeKey: $purpose->getKey()->value,
                title: $purpose->getTitle(),
                description: $purpose->getDescription(),
                required: $purpose->isRequired(),
                granted: $consent?->isGranted(),
                decisionAt: $consent?->getDecisionAt(),
            );
        }

        return $result;
    }

    #[Override]
    public function grantConsent(
        string $userUid,
        string $tenantUid,
        string $purposeKey,
        bool $granted,
        string $ipAddress,
        string $userAgent
    ): GdprConsentRecord {
        $tenant = new TenantRef($tenantUid);
        [, $purposesByKey] = $this->resolveActivePurposes($tenant);

        $purpose = $purposesByKey[$purposeKey] ?? null;
        if (null === $purpose) {
            throw new NotFoundException("consent-purpose/{$purposeKey}");
        }

        if ($purpose->isRequired() && !$granted) {
            throw ConstraintException::ofError('required_purpose_cannot_be_revoked', ['purposeKey'], [$purposeKey]);
        }

        $user = new UserRef($userUid);
        $filter = (new UserConsentPurposesFilter())->withUser($user)->withConsentPurpose($purpose);
        $existing = $this->writer->retrieveForUpdate($filter);
        $now = new DateTimeImmutable();

        if (null !== $existing) {
            $consent = $this->writer->update(
                $existing,
                $existing->update(
                    (new UserConsentPurposesAttributes())
                        ->granted($granted)
                        ->decisionAt($now)
                        ->ipAddress($ipAddress)
                        ->userAgent($userAgent)
                )
            );
        } else {
            $consent = $this->writer->create(
                UserConsentPurposes::create(
                    (new UserConsentPurposesAttributes())
                        ->uid(Random::uuid())
                        ->user($user)
                        ->consentPurpose($purpose)
                        ->granted($granted)
                        ->decisionAt($now)
                        ->ipAddress($ipAddress)
                        ->userAgent($userAgent)
                )
            );
        }

        return $this->toRecord($consent, $purpose);
    }

    /** @return GdprConsentRecord[] */
    #[Override]
    public function historyConsents(string $userUid): array
    {
        $filter = (new UserConsentPurposesFilter())->withUser(new UserRef($userUid));
        $records = $this->reader->list($filter)->values();

        usort($records, static function (UserConsentPurposes $a, UserConsentPurposes $b): int {
            $dateA = $a->getDecisionAt();
            $dateB = $b->getDecisionAt();
            if ($dateA === $dateB) {
                return 0;
            }
            if ($dateA === null) {
                return 1;
            }
            if ($dateB === null) {
                return -1;
            }
            return $dateB <=> $dateA;
        });

        return array_map(
            fn (UserConsentPurposes $r): GdprConsentRecord => $this->toRecord($r, $r->getConsentPurpose()),
            $records
        );
    }

    /**
     * Loads all purposes for the tenant, groups by key, keeps the one with the
     * highest activationDate per key. Returns the domain map and the raw entity
     * index in a single DB call.
     *
     * @return array{GdprConsentMap, array<string, ConsentPurpose>}
     */
    private function resolveActivePurposes(TenantRef $tenant): array
    {
        $all = $this->purposes->list((new ConsentPurposeFilter())->withTenant($tenant))->values();

        /** @var array<string, ConsentPurpose> $byKey */
        $byKey = [];
        foreach ($all as $purpose) {
            $key = $purpose->getKey()->value;
            $current = $byKey[$key] ?? null;
            if (null === $current || $this->isNewerActivation($purpose, $current)) {
                $byKey[$key] = $purpose;
            }
        }

        $items = array_map(
            static fn (ConsentPurpose $p): GdprConsentPurposeItem => new GdprConsentPurposeItem(
                uid: $p->uid(),
                key: $p->getKey()->value,
                title: $p->getTitle(),
                description: $p->getDescription(),
                required: $p->isRequired(),
            ),
            $byKey
        );

        return [GdprConsentMap::build(...array_values($items)), $byKey];
    }

    private function isNewerActivation(ConsentPurpose $candidate, ConsentPurpose $current): bool
    {
        $candidateDate = $candidate->getActivationDate();
        $currentDate = $current->getActivationDate();
        if (null === $candidateDate) {
            return false;
        }
        if (null === $currentDate) {
            return true;
        }
        return $candidateDate > $currentDate;
    }

    private function toRecord(UserConsentPurposes $consent, ConsentPurpose $purpose): GdprConsentRecord
    {
        return new GdprConsentRecord(
            uid: $consent->uid(),
            purposeUid: $purpose->uid(),
            purposeKey: $purpose->getKey()->value,
            title: $purpose->getTitle(),
            description: $purpose->getDescription(),
            required: $purpose->isRequired(),
            granted: $consent->isGranted(),
            decisionAt: $consent->getDecisionAt(),
            ipAddress: $consent->getIpAddress(),
            userAgent: $consent->getUserAgent(),
        );
    }

    private function resolveUser(string $tenant, string $username): ?UserRef
    {
        $byUid = $this->users->findOneByUid($username);
        if (null !== $byUid) {
            return $byUid;
        }

        $tenantEntity = $this->tenants->findOneByName($tenant);
        if (null === $tenantEntity) {
            return null;
        }

        return $this->users->findOneByTenantAndName($tenantEntity, $username);
    }

    private function resolveTenant(string $tenant): ?TenantRef
    {
        return $this->tenants->findOneByName($tenant);
    }
}
